function renderPages(){if(!current){$('pages').innerHTML='<tr><td colspan="7">No crawl is selected for this website.</td></tr>';$('tableCount').textContent='0';$('showing').textContent='No URLs checked';return}const search=$('search').value.toLowerCase(),status=$('statusFilter').value,segment=$('segment').value;const pages=current.pages.filter(p=>(!search||(p.url+' '+p.title).toLowerCase().includes(search))&&(!status||Math.floor((p.status||0)/100)===Number(status))&&(!segment||p.segment===segment));$('tableCount').textContent=current.pages.length;$('pages').innerHTML=pages.length?pages.slice(0,500).map(p=>`<tr class="page-row" data-url="${esc(p.url)}" tabindex="0" role="button" aria-label="Inspect ${esc(p.url)}"><td><span class="page-url">${esc(p.url)}</span><small>${esc(p.title||'Untitled page')}</small></td><td><span class="badge ${p.status>=400||!p.status?'error':p.status>=300?'notice':''}">${p.accessChallenge?'Verification':p.blocked?'Blocked':p.status||'Failed'}</span></td><td>${'<span class="'+(eligible(p)?'green':'muted')+'">'+esc(p.indexability?.label||'Not fully checked')+'</span>'}</td><td>${p.issues.length?'<span class="badge warning">'+p.issues.length+'</span>':'<span class="green">—</span>'}</td><td>${p.depth??'—'}</td><td>${p.wordCount??'—'}</td><td>${p.internalRank??'—'}</td></tr>`).join(''):'<tr><td colspan="7"><div class="empty"><h3>No matching URLs</h3><p>Try a different filter or wait for the crawl to discover pages.</p></div></td></tr>';$('showing').textContent=`Showing ${Math.min(pages.length,500)} of ${pages.length} matching URLs`;document.querySelectorAll('.page-row').forEach(row=>{row.onclick=()=>inspect(row.dataset.url);row.onkeydown=e=>{if(e.key==='Enter')inspect(row.dataset.url)}})}
