function renderIssues(){const findings=(current?.pages||[]).flatMap(p=>p.issues.map(i=>({...i,url:p.url}))).filter(i=>!$('issueType').value||i.type===$('issueType').value);$('issuesList').innerHTML=findings.length?findings.slice(0,1000).map(i=>`<div class="list-item"><div><span class="badge ${esc(i.severity)}">${esc(i.type)}</span><p><strong>${esc(i.message)}</strong></p><p>${esc(i.url)}</p></div></div>`).join(''):'<p>No findings to display.</p>'}$('issueType').onchange=renderIssues;
