async function refreshLibrary(){if(publicVisitor){library=[];$('savedList').innerHTML='';return}library=await api('/api/crawls'+(showRemoved?'?archived=true':''));$('savedList').innerHTML=library.map(j=>`<div class="list-item"><div><strong>${esc(j.url)}</strong><p>${esc(new Intl.DateTimeFormat('en-GB',{dateStyle:'full',timeStyle:'long'}).format(new Date(j.started)))} · ${j.count} URLs · ${esc(j.state)}</p><p>${esc(j.submission?.countryName||'Location not recorded')} · ${esc(j.submission?.role||'Earlier audit')} ${j.submission?.countryName?'(approximate IP country)':''}</p></div><button class="secondary" data-open="${j.id}">Open crawl →</button><button class="secondary" data-archive="${j.id}">${showRemoved?'Restore':'Remove'}</button></div>`).join('')||'<p>No saved crawls yet.</p>';document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=catchError(async()=>{await api('/api/crawls/'+b.dataset.archive+'/'+(showRemoved?'restore':'archive'),'POST',{});await refreshLibrary();message(showRemoved?'Audit restored.':'Audit removed from Saved Audits. You can restore it under Removed audits.')}));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=catchError(async()=>{activeClient=null;auditData=null;current=await api('/api/crawls/'+b.dataset.open);$('url').value=current.config.url;$('limit').value=current.config.limit||100;config={...current.config};searchData=null;analyticsData=null;void loadSavedSearch(current.config.url);render();go('overview');poll();void catchError(()=>loadPublicAudit(current.config.url,false))()}));const opts=library.map(j=>`<option value="${j.id}">${esc(new Date(j.started).toLocaleString()+' · '+j.url+' · '+j.count+' URLs')}</option>`).join('');for(const id of ['before','after']){const previous=$(id).value;$(id).innerHTML=opts;if(previous)$(id).value=previous}if(library.length>1&&!$('before').value)$('before').selectedIndex=1}
