$('compareButton').onclick=catchError(async()=>{const before=$('before').value,after=$('after').value;if(!before||!after||before===after)throw Error('Select two different crawls');const changes=await api(`/api/compare?before=${before}&after=${after}`);$('comparison').innerHTML=changes.map(c=>`<div class="list-item"><div><span class="badge ${c.change==='removed'?'error':'notice'}">${esc(c.change)}</span><p><strong>${esc(c.url)}</strong></p><p>${esc(c.fields.join(', '))}${c.issuesAfter!==undefined?' · findings '+c.issuesBefore+' → '+c.issuesAfter:''}</p></div></div>`).join('')||'<p>No differences in tracked fields.</p>'});
