function renderGraph(){const pages=(current?.pages||[]).slice(0,150),n=pages.length;if(!n){$('graph').innerHTML='<p>Start or open a crawl to explore its link graph.</p>';return}const positions=new Map(pages.map((p,i)=>[p.url,{x:450+Math.cos(i*2*Math.PI/n)*340,y:215+Math.sin(i*2*Math.PI/n)*175}]));let edges='';for(const p of pages){const a=positions.get(p.url);for(const link of p.links||[]){const b=positions.get(link);if(b)edges+=`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#dce8e1"/>`}}$('graph').innerHTML=`<svg viewBox="0 0 900 430" role="img" aria-label="Internal link graph">${edges}${pages.map(p=>{const {x,y}=positions.get(p.url);return `<g><title>${esc(p.url)} · ${p.status}</title><circle cx="${x}" cy="${y}" r="${p.depth===0?9:5}" fill="${p.status>=400?'#cf746b':'#ae18fe'}"/><text x="${x+9}" y="${y+4}">${esc(new URL(p.url).pathname.slice(0,17))}</text></g>`}).join('')}</svg>`;const groups=new Map();for(const p of current.pages){const s=p.segment||'other';groups.set(s,(groups.get(s)||0)+1)}$('segments').innerHTML=[...groups].map(([s,count])=>`<div class="list-item"><strong>/${esc(s)}</strong><span>${count} URLs</span></div>`).join('')}
const featureCoverage=[
['Evidence-first SEO skill','Included','Confidence-labeled findings with evidence, impact, fix, effort, priorities, reference freshness, and full Markdown / HTML audit and action-plan exports.'],
['Social, images & readability','Included','Open Graph / Twitter Card observations, heading hierarchy, intrinsic image dimensions, and English readability estimates. These are review signals, not ranking guarantees.'],
['AI crawler policies & llms.txt','Included','Start-path policy for seven AI agents; optional llms.txt observation. These checks do not certify AI visibility.'],
['Broken links, errors & redirects','Included','HTTP status and redirect targets for crawled same-origin URLs. External links are discovered but not fetched; redirect chains outside the origin are not followed.'],
['Page titles & metadata','Included','Missing, long and repeated titles; meta descriptions. Lightweight HTML extraction; malformed markup and unusual encodings need review.'],
['Meta robots & directives','Included','robots/googlebot metadata and X-Robots-Tag; noindex findings. Full directive conflict resolution is not implemented.'],
['hreflang attributes','Included','Language syntax, repeated languages, and return links where both URLs were crawled.'],
['Exact duplicate pages','Included','SHA-256 match of complete HTML.'],
['XML sitemaps','Included','Export successful HTML URLs without noindex and without alternate canonicals.'],
['Site visualisations','Included','Link graph and directory segmentation.'],
['Crawl limit & configuration','Included','1–2,000 URLs, depth, delay, user agent, URL filters, source search and extraction.'],
['Scheduling','Included','Persistent hourly intervals; server must be running.'],
['Save & open crawls','Included','Automatic local snapshots, JSON export/import, saved crawl library.'],
['JavaScript rendering','Browser setup','Playwright Chromium; install using npm run install-browser.'],
['Crawl comparison','Advanced API','Added, removed, status, title, description, robots, canonical and HTML changes.'],
['Near duplicate content','Included','Jaccard similarity of text trigrams; configurable threshold. Comparison is bounded to first 3,000 words per page and may include template text.'],
['Custom robots.txt','Included','Override rules and toggle enforcement. Robots handling supports user-agent groups and allow/disallow patterns; crawl-delay is not implemented; bounded XML sitemap discovery is included.'],
['Mobile usability','Basic + browser','Viewport metadata and horizontal overflow at 390px. Full device lab testing is outside this build.'],
['AMP crawling & validation','Optional runtime','Discovers same-origin amphtml URLs; amphtml-validator checks AMP documents when enabled. It may download the validator runtime.'],
['Structured data & validation','Expanded basic','JSON-LD syntax, context, entity type, graph and placeholder checks. Full schema.org semantics, microdata, RDFa and Google rich-result eligibility are not validated.'],
['Spelling & grammar','Integration','LanguageTool endpoint; run against supplied text or first page.'],
['Custom source search & extraction','Included','Regex source search; regex captures; CSS extraction with rendering. Regex should be trusted and bounded to avoid excessive processing.'],
['Custom JavaScript','Browser setup','User-provided page expression executed in the browser.'],
['OpenAI & Gemini','Credentials required','On-demand SEO analysis using crawl data. Select model through environment variables. Not an automatic per-URL AI crawl.'],
['Google Analytics & Search Console','Credentials required','Google sign-in with encrypted refresh tokens, property selection, dated search clicks, query/page rows and period comparison. Requires Google OAuth app setup. Manual access tokens also supported.'],
['PageSpeed Insights','Integration','On-demand mobile and desktop performance reports; quota depends on Google project.'],
['Accessibility auditing','Basic + browser','Static language/alt checks; axe-core browser violations with rendering. Automated checks do not replace manual accessibility review.'],
['Link metrics integration','Adapter required','Internal iterative link score is included; external metrics require your provider adapter endpoint.'],
['Forms based authentication','Browser setup','Username/password selectors and login submission in a shared session. MFA, CAPTCHA and interactive SSO are not automated.'],
['Segmentation','Included','Directory grouping, search, HTTP status and segment filters.'],
['Looker Studio crawl report','CSV handoff','Export CSV and upload it to Looker Studio. A native Community Connector or hosted report template is not included.'],
['Free technical support','Documentation','Setup guide and troubleshooting are included. An ongoing staffed support service is not provided.']];
