function renderAuditFindings(){if(!auditData)return;const findings=auditData.findings.filter(f=>(!$('auditConfidence').value||f.confidence===$('auditConfidence').value)&&(!$('auditPriority').value||f.priority===Number($('auditPriority').value)));$('auditFindings').innerHTML=findings.slice(0,1000).map(f=>'<article class="audit-finding"><div class="finding-top"><span class="badge '+esc(f.severity)+'">P'+f.priority+'</span><span class="badge '+(f.confidence==='Confirmed'?'':'notice')+'">'+f.confidence+'</span><small>'+esc(f.category)+' · '+f.impactLevel+' impact · '+f.effort+' effort</small></div><h3>'+esc(f.finding)+'</h3><p class="finding-url">'+esc(f.url)+'</p><details><summary>Evidence</summary><pre>'+esc(JSON.stringify(f.evidence,null,2))+'</pre></details><p><b>Impact:</b> '+esc(f.impact)+'</p><p><b>Fix:</b> '+esc(f.fix)+'</p></article>').join('')||'<p>No matching findings. Missing evidence does not count as a pass.</p>'}
$('auditConfidence').onchange=renderAuditFindings;$('auditPriority').onchange=renderAuditFindings;

