function renderTraffic(){const options=graphOptions(),previous=$('graphMetric').value;$('graphMetric').innerHTML=options.map(([v,label])=>'<option value="'+v+'">'+label+'</option>').join('');if(options.some(([v])=>v===previous))$('graphMetric').value=previous;$('graphMetric').disabled=!options.length;const metric=$('graphMetric').value,isSearch=['clicks','impressions'].includes(metric),source=isSearch?searchData:analyticsData,range=source?.range||source,field=metric==='clicks'?'traffic':metric;const rows=source?.history||[],old=source?.historyPrevious||[];$('performanceTitle').textContent=graphTab==='backlinks'?'Backlink performance':graphTab==='paid'?'Paid search performance':'Performance';$('trafficCaption').textContent=source?(isSearch?'Google Search Console':'Google Analytics 4')+' · '+range.startDate+' to '+range.endDate:'';$('graphNote').textContent=graphTab==='backlinks'?'Google’s standard search and analytics reports do not supply a complete backlink history or Ahrefs DR/UR. This view stays unavailable.':source?(source.note||'')+(analyticsData?.limited&&!isSearch?' Google flagged reporting thresholds, sampling or row limits.':''):'Connect the required Google property to load this metric.';if(graphTab==='backlinks'||!source||!rows.length){$('trafficGraph').innerHTML='<div class="empty"><h3>'+ (graphTab==='backlinks'?'Backlink history is not available.':!source?'Connect Google to view this trend.':'No observations were returned for this period.')+'</h3><p>Only measured data is shown. Historical values are not inferred.</p></div>';return}const values=rows.map(r=>Number(r[field]||0)),oldValues=old.map(r=>Number(r[field]||0)),compare=isComparing()&&old.length,max=Math.max(1,...values,...(compare?oldValues:[])),w=1000,h=220,series=(items,field,startDate)=>items.map((r,i)=>({x:55+Math.max(0,Math.min(1,(new Date(r.date)-new Date(startDate))/Math.max(86400000,new Date(range.endDate)-new Date(range.startDate))))*920,y:190-Number(r[field]||0)/max*160,...r})),points=series(rows,field,range.startDate),before=series(old,field,range.previousStart||source.previousStart),line=(p,color,dash='')=>'<polyline fill="none" stroke="'+color+'" stroke-width="2.5" '+(dash?'stroke-dasharray="6 5"':'')+' points="'+p.map(v=>v.x+','+v.y).join(' ')+'"/>'+p.map(v=>'<circle tabindex="0" cx="'+v.x+'" cy="'+v.y+'" r="3" fill="'+color+'"><title>'+esc(v.date)+' · '+number(v[field])+'</title></circle>').join('');$('trafficGraph').innerHTML='<div class="chart-key"><span>● Current period</span>'+(compare?'<span class="previous-series">┄ Previous period (aligned by day in period)</span>':'')+'</div><svg viewBox="0 0 1000 250" role="img" aria-label="'+esc($('graphMetric').selectedOptions[0]?.textContent||'Performance')+' by date">'+[0,.5,1].map(f=>'<line x1="55" x2="975" y1="'+(190-f*160)+'" y2="'+(190-f*160)+'" stroke="#edf0f2"/><text x="2" y="'+(195-f*160)+'">'+number(max*f)+'</text>').join('')+line(points,'#ed8a32')+(compare?line(before,'#8874bb',true):'')+[0,Math.floor((rows.length-1)/2),rows.length-1].map(i=>'<text x="'+points[i].x+'" y="240" text-anchor="middle">'+new Date(rows[i].date+'T00:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})+'</text>').join('')+'</svg>'}
function renderCountries(){const paid=countryMode==='paid',g=analyticsData,r=searchData,useGoogleClicks=!paid&&!!r,available=paid?!!g:!!r||!!g;const total=useGoogleClicks?r.organicClicks:paid?g?.paidSessions:g?.organicSessions;$('countrySource').textContent=useGoogleClicks?'Organic clicks · Search Console':available?(paid?'Paid':'Organic')+' sessions · GA4':'Connect a Google property';$('countryRows').innerHTML=countries.map(([ga,sc,name])=>{const row=useGoogleClicks?r.countries?.find(c=>c.code===sc):g?.countries?.find(c=>c.code===ga),previous=useGoogleClicks?r.countriesPrevious?.find(c=>c.code===sc):g?.countriesPrevious?.find(c=>c.code===ga),value=row?(useGoogleClicks?row.traffic:row[paid?'paid':'organic']):null,old=previous?(useGoogleClicks?previous.traffic:previous[paid?'paid':'organic']):null;return '<tr><td>'+name+'</td><td>'+number(value)+periodDelta(value,old)+'</td><td>'+(value!=null&&total>0?number(value/total*100)+'%':'—')+'</td><td>'+(useGoogleClicks&&row?number(row.keywords):'—')+'</td></tr>'}).join('');$('countryNote').textContent=!available?'No data connection for this channel yet.':useGoogleClicks?'Share is of all reported Google organic clicks. Keywords are distinct returned queries per country; privacy limits apply. Missing country rows show a dash.':'Share is of worldwide sessions for the selected channel. GA4 does not provide organic or paid keyword counts by country. Missing country rows show a dash.';$('countryOrganic').classList.toggle('active',!paid);$('countryPaid').classList.toggle('active',paid)}
