function performanceMarkup(value,detail=false){if(value?.status!=='ready')return sourceMessage(value);const devices=value.data.devices||{mobile:{status:'ready',...value.data},desktop:{status:'not-run',reason:'Run a new speed test to collect desktop results.'}};return '<div class="device-performance">'+Object.entries(devices).map(([device,d])=>'<section><h3>'+esc(device==='mobile'?'Mobile':'Desktop')+'</h3>'+(d.status!=='ready'?'<p>'+esc(d.reason||'Not tested')+'</p>':'<div class="performance-scores"><article><strong class="'+(d.scores.performance==null?'muted':d.scores.performance>=90?'green':d.scores.performance>=50?'amber':'red')+'">'+number(d.scores.performance)+'</strong><span>Overall performance / 100</span></article></div>'+(detail?'<div class="performance-scores">'+Object.entries(d.scores).filter(([k])=>k!=='performance').map(([k,v])=>'<article><strong>'+number(v)+'</strong><span>'+esc(k.replaceAll('-',' '))+'</span></article>').join('')+'</div><p>First contentful paint: '+esc(d.lab.fcp||'Not returned')+' · Largest contentful paint: '+esc(d.lab.lcp||'Not returned')+' · Speed index: '+esc(d.lab.speedIndex||'Not returned')+' · Total blocking time: '+esc(d.lab.tbt||'Not returned')+' · Cumulative layout shift: '+esc(d.lab.cls||'Not returned')+'</p>':'')+'<p class="source-stamp">Tested '+esc(d.testedAt||d.retrievedAt||value.retrievedAt)+'</p>')+'</section>').join('')+'</div><p>Google PageSpeed Insights · One tested page per device. Lab scores can vary between runs.</p>'+(detail?'<p>Tested page: '+esc(value.url||value.data.testedURL||'Not returned')+'</p>':'')}
function backlinkMarkup(value,detail=false){if(value?.status!=='ready')return sourceMessage(value);const d=value.data;return '<div class="backlink-metrics"><article><strong>'+number(d.authority)+'</strong><span>Crawly authority</span></article><article><strong>'+number(d.referringDomains)+'</strong><span>Referring domains</span></article><article><strong>'+number(d.backlinks)+'</strong><span>Reported links</span></article></div><p class="source-stamp">Crawly index · retrieved '+esc(value.retrievedAt)+'</p><p>'+esc(value.note)+'</p>'+(detail?'<table><thead><tr><th>Reported source domain</th><th>Links</th><th>Provider rating</th></tr></thead><tbody>'+d.links.map(l=>'<tr><td>'+esc(l.domain)+'</td><td>'+number(l.count)+'</td><td>'+esc(l.rating)+'</td></tr>').join('')+'</tbody></table>':'')}
function targetWebsite(){return !$('view-integrations').classList.contains('hidden')?$('clientWebsite').value||$('url').value:$('url').value}
function renderPublicAudit(){const pages=current?.pages||[],issues=pageIssues(),tech=issues.filter(i=>!onpageTypes.has(i.type)),onpage=issues.filter(i=>onpageTypes.has(i.type));$('publicWebsite').textContent=current?new URL(current.config.url).hostname:'Enter a website to start';$('publicSummary').innerHTML=[['URLs requested',current?pages.length:null,current?.accessBlocked?'Access verification prevented a complete audit':'A sample within your crawl limit','technical'],['Technical findings',current?tech.length:null,'Crawlability, errors and directives','technical'],['On-page findings',current?onpage.length:null,'Content, titles and page metadata','onpage']].map(([label,n,note,view])=>'<button class="summary-card" data-public-view="'+view+'"><span>'+label+'</span><strong>'+number(n)+'</strong><small>'+note+'</small></button>').join('');document.querySelectorAll('[data-public-view]').forEach(b=>b.onclick=()=>go(b.dataset.publicView));$('technicalFindings').innerHTML=issueRows(tech);$('onpageFindings').innerHTML=issueRows(onpage);$('onpagePages').innerHTML=pages.filter(p=>!p.accessChallenge&&p.status===200&&/html/i.test(p.contentType||'')).slice(0,300).map(p=>'<tr><td>'+esc(p.url)+'</td><td>'+esc(p.title||'Missing title')+'</td><td>'+esc(p.description||'Missing description')+'</td><td>'+number(p.wordCount)+'</td></tr>').join('')||'<tr><td colspan="4">No HTML pages checked yet.</td></tr>';$('overviewPerformance').innerHTML=performanceMarkup(publicAuditData?.performance);$('performanceDetails').innerHTML=performanceMarkup(publicAuditData?.performance,true);$('overviewBacklinks').innerHTML=backlinkMarkup(publicAuditData?.backlinks);$('backlinkDetails').innerHTML=backlinkMarkup(publicAuditData?.backlinks,true);const recommendations=auditData&&current&&auditData.url===current.config.url?auditData.findings:[];$('overviewRecommendations').innerHTML=recommendations.length?recommendations.slice(0,4).map(f=>'<article class="audit-finding"><span class="badge '+esc(f.severity)+'">P'+f.priority+'</span><h3>'+esc(f.finding)+'</h3><p><b>Recommended action:</b> '+esc(f.fix)+'</p></article>').join(''):'<p>Finish a crawl to generate the prioritized SEO action plan.</p>';$('performanceRecommendations').innerHTML=(publicAuditData?.performance?.data?.recommendations||[]).length?'<h3>PageSpeed recommendations</h3>'+publicAuditData.performance.data.recommendations.map(r=>'<article class="audit-finding"><span class="badge notice">Device lab test</span><h3>'+esc((r.strategy?r.strategy+' · ':'')+r.title)+'</h3><p>'+esc(r.description)+'</p><p>'+esc(r.display||'')+'</p></article>').join(''):'';if(['complete','imported'].includes(current?.state)&&recommendationJob!==current.id){recommendationJob=current.id;const id=current.id;void api('/api/crawls/'+id+'/audit').then(value=>{if(current?.id===id){auditData=value;renderPublicAudit()}}).catch(e=>message(e.message,true))}}
async function loadPublicAudit(url,run=false,force=false){const seq=++publicRequest;clearTimeout(publicTimer);if(publicAuditURL!==url)publicAuditData=null;publicAuditURL=url;renderPublicAudit();if(run)await api('/api/public/analyse','POST',{url,forcePerformance:force});const update=async(count=0)=>{const value=await api('/api/public?url='+encodeURIComponent(url));if(seq!==publicRequest)return;publicAuditData=value;renderPublicAudit();if(count<80&&(count<1||[value.performance,value.backlinks].some(v=>!v||v.refreshing||['not-run','running'].includes(v.status))))publicTimer=setTimeout(()=>void catchError(()=>update(count+1))(),3000)};await update();if(!run&&seq===publicRequest&&[publicAuditData?.performance,publicAuditData?.backlinks].some(v=>!v||v.status==='not-run')){await api('/api/public/analyse','POST',{url})}}
$('refreshPublic').onclick=$('retryPerformance').onclick=catchError(async()=>{if(!current)throw Error('Start or open a crawl first');await loadPublicAudit(current.config.url,true,true)});
$('newAudit').onclick=()=>{if(current?.state==='running'){go('overview');return message('A crawl is still running. Finish it before starting another.')}++clientRequest;activeClient=null;document.body.classList.add('welcome-mode');$('welcomeUrl').value=''};
$('welcomeClients').onclick=()=>go('clients');
async function refreshClients(){clientItems=await api('/api/clients');$('welcomeClients').classList.toggle('hidden',!clientItems.length);$('clientList').innerHTML=clientItems.length?clientItems.map(c=>'<article class="client-list-item"><div><h3>'+esc(c.name)+'</h3><p>'+esc(c.url)+'</p><span class="badge">'+(c.site?'Search Console':'')+(c.site&&c.property?' + ':'')+(c.property?'GA4':'')+'</span><p>Baseline: '+(c.baselineCrawlId?'Audit saved':'Waiting for first completed audit')+' · Last Google refresh: '+esc(c.lastRefresh||'Not refreshed yet')+'</p></div><button class="primary" data-client="'+esc(c.id)+'">Open client overview →</button></article>').join(''):'<p>No connected clients yet. Open Connections & Settings to save a website with its Google properties.</p>';document.querySelectorAll('[data-client]').forEach(b=>b.onclick=catchError(()=>openClient(b.dataset.client)))}
const daysInRange=r=>Math.max(1,Math.round((new Date(r.endDate)-new Date(r.startDate))/86400000)+1);
function renderClientProgress(detail){const c=detail.client,p=detail.progress,r=detail.report,base=c.baselineGoogle||{},metrics=[];if(base.search&&r?.search)metrics.push(['Google clicks / day',r.search.organicClicks/daysInRange(r.search.range),base.search.clicks/daysInRange(base.search.range)]);if(base.analytics&&r?.analytics)metrics.push(['Sessions / day',r.analytics.sessions/daysInRange(r.analytics.range),base.analytics.sessions/daysInRange(base.analytics.range)]);$('clientProgress').innerHTML='<div class="panel-title"><div><h2>'+esc(c.name)+' · progress since onboarding</h2><p>'+esc(c.url)+'</p></div><button class="primary" id="refreshClient">Refresh this client’s Google reports</button></div><div class="client-progress-stats">'+(p?[['No longer detected',p.resolved],['Still detected',p.remaining],['Not rechecked',p.unchecked],['New findings',p.newIssues]].map(([label,n])=>'<article><strong>'+number(n)+'</strong><span>'+label+'</span></article>').join(''):'<p>Complete a website audit to establish a technical baseline.</p>')+metrics.map(([label,n,old])=>'<article><strong>'+number(n)+change(n,old)+'</strong><span>'+label+' vs onboarding period</span></article>').join('')+'</div><p class="hint">'+esc(p?.note||'Google and technical baselines are saved separately.')+'</p><p class="hint">Google progress uses daily averages when comparing periods of different lengths. This shows reported changes, not proof that SEO work caused them. '+esc(Object.values(r?.errors||{}).join(' · '))+'</p>';$('refreshClient').onclick=catchError(async()=>{const id=activeClient?.client.id;if(!id)return;$('refreshClient').disabled=true;message('Refreshing this client’s Google data…');try{const period=$('reportPeriod').value;await api('/api/clients/'+id+'/refresh?period='+period,'POST',{});if(activeClient?.client.id===id&&period===$('reportPeriod').value)await openClient(id)}finally{if($('refreshClient'))$('refreshClient').disabled=false}})}
async function openClient(id){clearTimeout(timer);const seq=++clientRequest,period=$('reportPeriod').value,detail=await api('/api/clients/'+id+'?period='+period);if(seq!==clientRequest)return;activeClient=detail;searchData=detail.report?.search||null;analyticsData=detail.report?.analytics||null;$('url').value=detail.client.url;$('clientWebsite').value=detail.client.url;$('clientName').value=detail.client.name;const latest=detail.latestCrawl?await api('/api/crawls/'+detail.latestCrawl.id):null;if(seq!==clientRequest)return;current=latest;publicAuditData=null;++publicRequest;clearTimeout(publicTimer);go('client-dashboard');render();renderSearch();renderClientProgress(detail);$('heading').textContent=detail.client.name+' · client overview';$('crumb').textContent='Connected Clients / '+detail.client.name;$('pdfTop').disabled=false;message(detail.report?'Client report loaded.':'No Google report saved for this period yet. Click Refresh this client’s Google reports.');await refreshClients()}
$('saveClient').onclick=catchError(async()=>{const url=normalizeInput($('clientWebsite').value||$('url').value);$('saveClient').disabled=true;$('clientConnectionMessage').textContent='Checking website property access…';try{const c=await api('/api/clients','POST',{name:$('clientName').value,url,connectionId:$('googleAccount').value,site:$('searchProperty').value,property:$('analyticsProperty').value});$('clientConnectionMessage').textContent='Client saved. Its Google data and baseline are kept separate from other websites.';await refreshClients();await openClient(c.id)}finally{$('saveClient').disabled=false}});
$('googleAccount').onchange=()=>{$('searchProperty').innerHTML='<option value="">Select a property for this Google account</option>';$('analyticsProperty').innerHTML='<option value="">Select a GA4 property for this account</option>'};
const oldPeriodChange=$('reportPeriod').onchange;$('reportPeriod').onchange=catchError(async()=>{if(activeClient&&document.body.dataset.dashboard==='client')return openClient(activeClient.client.id);return oldPeriodChange()});
const oldRefreshPerformance=$('refreshPerformance').onclick;$('refreshPerformance').onclick=()=>{if(activeClient&&document.body.dataset.dashboard==='client')$('refreshClient')?.click();else oldRefreshPerformance()};
const oldPDF=$('pdfTop').onclick;$('pdfTop').onclick=catchError(async()=>{if(!activeClient||document.body.dataset.dashboard!=='client')return oldPDF();const response=await fetch('/api/clients/'+activeClient.client.id+'/report?format=pdf&period='+$('reportPeriod').value);if(!response.ok)throw Error((await response.json()).error||'Client PDF export failed');const href=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=href;link.download='CrawlStudio-Client-Report.pdf';link.click();setTimeout(()=>URL.revokeObjectURL(href),30000)});
void catchError(init)();

$('removedAudits').onclick=catchError(async()=>{showRemoved=!showRemoved;$('removedAudits').textContent=showRemoved?'Back to Saved Audits':'Removed audits';await refreshLibrary()});
